        fn a_failure_without_errno_is_no_os_error() {
            let e = outcome(-1, 0).unwrap_err();
            assert_eq!(e.kind(), io::ErrorKind::Other);
            assert_eq!(e.raw_os_error(), None);
            assert_eq!(e.to_string(), "fprintf failed without setting errno");
        }
    }
}

